record.field:
for picking in records:
    if picking.picking_type_code != 'outgoing' or picking.state != 'done':
        continue

    for move in picking.move_ids_without_package:
        product = move.product_id.product_tmpl_id
        qty = move.quantity_done or 0
        carton_type = product.carton_type or 'loose'

        materials = []
        if carton_type == 'master':
            materials = product.mc_packing_material_ids
        else:
            materials = product.loose_packing_material_ids

        for mat in materials:
            if 'box' in mat.name.lower():
                qty_per_unit = 1.0 / 5.0 if carton_type == 'master' else 1.0
            elif 'bubble' in mat.name.lower():
                qty_per_unit = 1.0
            else:
                qty_per_unit = 1.0

            total_qty = qty * qty_per_unit

            stock_move = picking.env['stock.move'].create({
                'name': f'PACKING: {mat.display_name}',
                'product_id': mat.id,
                'product_uom_qty': total_qty,
                'product_uom': mat.uom_id.id,
                'location_id': picking.location_id.id,
                'location_dest_id': picking.env.ref('stock.stock_location_scrapped').id,
                'picking_id': picking.id,
            })
            stock_move._action_confirm()
            stock_move._action_done()
